# Confirmation (not used in the proof): the proof of (F^93_4) from Proposition (F*_3).
#  (1) For every level-4 state b and random left parts (exact words, exact2.py): the identities of the transfer
#      (cells r-3, r-2 of Fb) and of Steps 1, 2 and 4 -- the configurations b~ used lie in the set of (F*_3) for Fb
#      and outside E, and F^{-1} b~ has the stated tip and cell r-2.
#  (2) Closure: the relation generated by (F*_3) applied to b, Fb and F^{-1}b (graphs2.py) joins each of the five
#      sets of (F^93_4) into one strongly connected class.
import itertools,random
from exact2 import Fw,Bw
from engine2 import vcell,f2 as f
A=[(0,0),(0,1),(1,0),(1,1)]
X5={(0,(1,1)),(1,(1,1)),(2,(1,1)),(3,(1,0)),(5,(0,1))}
R=12
def word(th,cells,pad):   # cells on [-4,0]; pad on [-4-len(pad),-5]; vacuum on [1,R]
    return list(pad)+list(cells)+[vcell(th,i) for i in range(1,R+1)], -4-len(pad)
def cells_of(w,off,lo,hi): return tuple(w[i-off] for i in range(lo,hi+1))
def isexc3(th,c2,c1,c0): return c2==(0,0) and c1==(1,1) and (th,c0) in X5
def inS3minusE(th0,x,th1,xt):
    """x, xt: cells on [-3,0] of configurations agreeing left of -3; level-3 class + non-exceptional"""
    if x[0]!=xt[0]: return False
    if xt[3]==vcell(th1,0): return False
    if x[0]==(0,0) and ((x[1]==(1,1))!=(xt[1]==(1,1))): return False
    return not isexc3(th1,xt[1],xt[2],xt[3])
def Finv_state(th,wt,off):
    """apply F^{-1} to the word wt (cells of b~), return (phase, cells on [-4,0])"""
    w2=Bw(wt); off2=off+1
    return (th-1)%6, cells_of(w2,off2,-4,0)
rng=random.Random(3); cnt={}
def tick(k): cnt[k]=cnt.get(k,0)+1
for th in range(6):
  for cs in itertools.product(A,repeat=5):
    if cs[-1]==vcell(th,0): continue
    (u0,v0),(u1,v1),(u2,v2),(u3,v3),(u4,v4)=cs
    for trial in range(3):
        pad=[(rng.randint(0,1),rng.randint(0,1)) for _ in range(4)]
        w,off=word(th,cs,pad)
        Fb=Fw(w); offF=off+1; Fc=cells_of(Fb,offF,-4,0)
        alpha=u1^f(v0,v1,v2); beta=u2^f(v1,v2,v3)
        assert Fc[1]==(v1,alpha) and Fc[2]==(v2,beta)            # transfer lemma (b)
        def tilde(c2,c1,c0,thn):
            """Fb with cells r-2,r-1,r replaced, phase thn (of b~); returns F^{-1}b~ state or None"""
            if c0==vcell(thn,0): return None
            wt=list(Fb); 
            for i,c in zip((-2,-1,0),(c2,c1,c0)): wt[i-offF]=c
            for i in range(1,R): wt[i-offF]=vcell(thn,i)
            return Finv_state(thn,wt,offF)
        # Step 2: v1=0
        if v1==0 and not (u1==0 and (u2,v2)==(0,1)):
            for w1 in (0,1):
              for c0 in A:
                for thn in range(6):
                    c2=(1-v2,v2); c1=(w1,rng.randint(0,1))
                    r=tilde(c2,c1,c0,thn)
                    if r is None: continue
                    assert inS3minusE(None,Fc[1:],thn,(Fc[1],c2,c1,c0))
                    thp,bp=r
                    assert bp[0]==cs[0] and bp[1]==(1-u1,0), (cs,bp)
                    assert bp[2]==((1,1) if v2==0 else (w1,0))
                    tick('step2')
        # Step 4: v0=1, v1=1
        if v0==1 and v1==1:
            for c0 in A:
                for thn in range(6):
                    c2=(1-v2,1); c1=(rng.randint(0,1),rng.randint(0,1))
                    r=tilde(c2,c1,c0,thn)
                    if r is None: continue
                    assert inS3minusE(None,Fc[1:],thn,(Fc[1],c2,c1,c0))
                    assert r[1][0]==cs[0] and r[1][1]==(1-u1,1)
                    tick('step4')
        # Step 1, exceptional target b' (tip of b, cells r-2=00, r-1=11, (th',b'_r) in X5), from b with v2=0
        if v2==0 and not (u1==0 and v1==0 and (u2,v2)==(1,1)):
            for (thp,c0) in X5:
                bp=(cs[0],cs[1],(0,0),(1,1),c0)
                if c0==vcell(thp,0): continue
                wp,offp=word(thp,bp,pad)
                Fbp=Fw(wp); Fcp=cells_of(Fbp,offp+1,-4,0)
                assert Fcp[0]==Fc[0] and Fcp[1]==Fc[1]              # agree left of r-2
                assert Fcp[2]==(0,0) and Fcp[3]==(1,0)
                assert inS3minusE(None,Fc[1:],(thp+1)%6,Fcp[1:])
                tick('step1exc')
print('transfer and Steps 1, 2, 4: all identities hold',sorted(cnt.items()),flush=True)
from collections import defaultdict
from graphs2 import build
S3,Z3,M3=build(3)
S4,Z4,M4=build(4)
def reach(adj,s):
    seen={s};st=[s]
    while st:
        x=st.pop()
        for y in adj[x]:
            if y not in seen: seen.add(y);st.append(y)
    return seen
EXC={(0,(1,1)),(1,(1,1)),(2,(1,1)),(3,(1,0)),(5,(0,1))}
def isexc(s):
    th,cs=s
    return cs[-3]==(0,0) and cs[-2]==(1,1) and (th,cs[-1]) in EXC
def ccls(s):
    th,cs=s; e,t=cs[0],cs[1]
    return (e, (t==(1,1)) if e==(0,0) else None)
cls3=defaultdict(set)
for s in S3: cls3[ccls(s)].add(s)
A3={s:set(M3[s].values()) for s in S3}
ok=all({x for x in cls3[ccls(s)] if not isexc(x)}<=reach(A3,s)<=cls3[ccls(s)] for s in S3)
assert ok
def Fstate(b,ell):
    th,cs=b; outs=set()
    for pad in [(0,0),(0,1),(1,0),(1,1)]:
        w=[pad]*3+list(cs)+[vcell(th,i) for i in range(1,8)]
        w2=Fw(w) if ell==1 else Bw(w)
        outs.add(((th+ell)%6,tuple(w2[i+6] for i in range(-3,1))))
    assert len(outs)==1
    return outs.pop()
FS={(b,ell):Fstate(b,ell) for b in S4 for ell in (1,-1)}
INV=defaultdict(set)
for (b,ell),y in FS.items(): INV[(ell,b[1][0],y)].add(b)
def build_rel(exc_ok):
    G=defaultdict(set)
    for b in S4:
        x=(b[0],b[1][1:])
        for y in cls3[ccls(x)]:
            if exc_ok or not isexc(y): G[b].add((y[0],(b[1][0],)+y[1]))
        for ell in (1,-1):
            x=FS[(b,ell)]
            for y in cls3[ccls(x)]:
                if exc_ok or not isexc(y): G[b]|=INV[(ell,b[1][0],y)]
    return G
C4=defaultdict(set)
for s in S4: C4[ccls(s)].add(s)
for exc_ok in (False,):
    G=build_rel(exc_ok)
    res=[]
    for k,Sset in C4.items():
        good=all(reach(G,x)==Sset for x in Sset)
        res.append((k,len(Sset),good))
    assert all(g for _,_,g in res)
    print('closure: Proposition (F*_3) for b, Fb, F^-1 b joins each of the five sets of (F_4) into one class:',res)
